import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import { planTrip } from '../api';

const userTypeOptions = [
  { value: 'solo', label: 'Solo' },
  { value: 'female_solo', label: 'Solo Female' },
  { value: 'group', label: 'Group' },
  { value: 'family', label: '👨‍👩‍👧 Family' },
  { value: 'children', label: '👶 Children' },
  { value: 'temple', label: '🛕 Temple' },
];

export default function Planner() {
  const [user, setUser] = useState(null);
  const [form, setForm] = useState({ start: '', destination: '', budget: '', days: '', user_type: 'solo', people_count: 1 });
  const [result, setResult] = useState(null);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [panicVisible, setPanicVisible] = useState(false);
  const [mapFallback, setMapFallback] = useState(false);
  const navigate = useNavigate();

  useEffect(() => {
    const stored = localStorage.getItem('trip-planner-user');
    if (!stored) {
      navigate('/login');
      return;
    }
    setUser(JSON.parse(stored));
  }, [navigate]);

  const handleLogout = () => {
    localStorage.removeItem('trip-planner-user');
    navigate('/login');
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setForm((prev) => ({ ...prev, [name]: name === 'people_count' ? Number(value) : value }));
  };

  const onSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);
    try {
      const response = await planTrip({
        ...form,
        budget: Number(form.budget),
        days: Number(form.days),
      });
      setResult(response.data);
      setPanicVisible(true);
    } catch (err) {
      setError(err.response?.data?.error || 'Could not plan trip');
      setResult(null);
    } finally {
      setLoading(false);
    }
  };

  const safety = form.user_type === 'female_solo';
  const group = form.user_type === 'group';
  const family = form.user_type === 'family';
  const children = form.user_type === 'children';
  const temple = form.user_type === 'temple';
  const googleApiKey = process.env.REACT_APP_GOOGLE_API_KEY;
  const preferEmbedApi = process.env.REACT_APP_PREFER_GOOGLE_EMBED_API === 'true';
  const keyBasedMapSrc = form.destination
    ? `https://www.google.com/maps/embed/v1/directions?key=${googleApiKey || 'YOUR_GOOGLE_API_KEY'}&origin=${encodeURIComponent(form.start)}&destination=${encodeURIComponent(form.destination)}`
    : '';
  const fallbackMapSrc = form.destination
    ? `https://maps.google.com/maps?saddr=${encodeURIComponent(form.start)}&daddr=${encodeURIComponent(form.destination)}&output=embed`
    : '';
  const mapSrc = mapFallback || !preferEmbedApi || !googleApiKey ? fallbackMapSrc : keyBasedMapSrc;

  useEffect(() => {
    setMapFallback(false);
  }, [form.start, form.destination, result]);

  const hotels = Array.isArray(result?.hotels) ? result.hotels : [];
  const restaurants = Array.isArray(result?.restaurants) ? result.restaurants : Array.isArray(result?.food_places) ? result.food_places : [];
  const policePlaces = Array.isArray(result?.police) ? result.police : [];
  const hospitalPlaces = Array.isArray(result?.hospitals) ? result.hospitals : [];
  const itinerary = Array.isArray(result?.itinerary) ? result.itinerary : [];
  const routeDistance = result?.distance || result?.route?.distance || 'N/A';
  const routeDuration = result?.duration || result?.route?.duration || 'N/A';

  return (
    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="grid grid-cols-1 lg:grid-cols-2 gap-4">
      <section className="bg-slate-800 rounded-xl shadow-lg p-6">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-2xl font-bold">Smart Budget Trip Planner</h1>
            <p className="text-slate-400">Welcome, {user?.name || 'Traveler'}</p>
          </div>
          <button onClick={handleLogout} className="bg-red-500 hover:bg-red-400 px-3 py-2 rounded-lg">Logout</button>
        </div>

        <form onSubmit={onSubmit} className="space-y-4 mt-6">
          <input name="start" value={form.start} onChange={handleChange} placeholder="Start Location" className="w-full p-3 rounded-lg bg-slate-700 border border-slate-600" required />
          <input name="destination" value={form.destination} onChange={handleChange} placeholder="Destination" className="w-full p-3 rounded-lg bg-slate-700 border border-slate-600" required />
          <div className="grid grid-cols-2 gap-2">
            <input type="number" name="budget" value={form.budget} onChange={handleChange} placeholder="Budget" className="p-3 rounded-lg bg-slate-700 border border-slate-600" required />
            <input type="number" name="days" value={form.days} onChange={handleChange} placeholder="Number of Days" className="p-3 rounded-lg bg-slate-700 border border-slate-600" required />
          </div>
          <div>
            <label className="block text-sm mb-1">Travel Type</label>
            <select name="user_type" value={form.user_type} onChange={handleChange} className="w-full p-3 bg-slate-700 rounded-lg border border-slate-600">
              {userTypeOptions.map((item) => <option key={item.value} value={item.value}>{item.label}</option>)}
            </select>
          </div>

          {(group || family) && (
            <input type="number" name="people_count" value={form.people_count} onChange={handleChange} placeholder="Number of People" className="w-full p-3 rounded-lg bg-slate-700 border border-slate-600" min={1} required />
          )}

          {error && <p className="text-red-300">{error}</p>}

          <motion.button type="submit" whileHover={{ scale: 1.02 }} className="w-full py-3 bg-cyan-600 hover:bg-cyan-500 rounded-lg font-semibold">
            {loading ? 'Planning your trip...' : 'Plan Trip'}
          </motion.button>
        </form>

        {result && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="mt-8 bg-slate-700 p-4 rounded-xl">
            <h2 className="text-xl font-bold mb-2">Trip Summary</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-3 mb-4">
              <div className="bg-slate-800 p-4 rounded-xl border border-slate-600">
                <p className="text-slate-400 text-sm">Distance</p>
                <p className="text-lg font-semibold">{routeDistance}</p>
              </div>
              <div className="bg-slate-800 p-4 rounded-xl border border-slate-600">
                <p className="text-slate-400 text-sm">Duration</p>
                <p className="text-lg font-semibold">{routeDuration}</p>
              </div>
            </div>
            <div className="grid grid-cols-2 gap-3 mb-4">
              <div className="bg-slate-800 p-3 rounded-lg">Travel: ₹{result.budget_breakdown.travel}</div>
              <div className="bg-slate-800 p-3 rounded-lg">Stay: ₹{result.budget_breakdown.stay}</div>
              <div className="bg-slate-800 p-3 rounded-lg">Food: ₹{result.budget_breakdown.food}</div>
              <div className="bg-slate-800 p-3 rounded-lg">Other: ₹{result.budget_breakdown.other}</div>
            </div>
            {(group || family) && <p className="mb-1">Cost per person: ₹{result.per_person_cost}</p>}
            <p className="mb-2">Remaining budget (est): ₹{result.remaining_budget}</p>
            {safety && <p className="text-emerald-300 font-semibold mb-2">🛡️ Safety mode enabled - Safe Route</p>}
            {family && <p className="text-cyan-300 font-semibold mb-2">👨‍👩‍👧 Family-Friendly Trip</p>}
            {children && <p className="text-purple-300 font-semibold mb-2">🎪 Fun Activities for Kids!</p>}
            {temple && <p className="text-orange-300 font-semibold mb-2">🙏 Spiritual Journey</p>}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-3 mt-4">
              <div className="bg-slate-800 p-4 rounded-xl border border-slate-600">
                <p className="text-slate-400 text-sm">Hotels</p>
                <p className="text-2xl font-bold">{hotels.length}</p>
              </div>
              <div className="bg-slate-800 p-4 rounded-xl border border-slate-600">
                <p className="text-slate-400 text-sm">Restaurants</p>
                <p className="text-2xl font-bold">{restaurants.length}</p>
              </div>
              <div className="bg-slate-800 p-4 rounded-xl border border-slate-600">
                <p className="text-slate-400 text-sm">Safety Places</p>
                <p className="text-2xl font-bold">{policePlaces.length + hospitalPlaces.length}</p>
              </div>
            </div>
          </motion.div>
        )}
      </section>

      <section className="bg-slate-800 rounded-xl shadow-lg p-6 relative">
        <h2 className="text-xl font-bold mb-2">Map & Nearby Places</h2>
        {!result ? (
          <p className="text-slate-400">Enter trip details to view route and points of interest.</p>
        ) : (
          <div className="space-y-3">
            <div className="bg-slate-900 rounded-lg h-64 overflow-hidden">
              {form.destination ? (
                <iframe
                  title="Route map"
                  className="w-full h-full"
                  src={mapSrc}
                  onError={() => setMapFallback(true)}
                />
              ) : (
                <div className="flex items-center justify-center h-full text-slate-500">Map preview requires destination</div>
              )}
            </div>
            {mapFallback && (
              <p className="text-xs text-amber-300">Using Google Maps fallback mode. Check Embed API key restrictions/billing for full directions embed.</p>
            )}
            <div className="space-y-3">
              <div>
                <p className="font-semibold mb-2">Hotels</p>
                <div className="grid gap-3 sm:grid-cols-2">
                  {hotels.slice(0, 4).map((hotel, idx) => (
                    <a key={`${hotel.name || idx}`} href={hotel.maps_url} target="_blank" rel="noreferrer" className="block rounded-xl border border-slate-600 bg-slate-900 p-4 hover:border-cyan-400 transition">
                      <p className="font-semibold">{hotel.name || 'Hotel'}</p>
                      <p className="text-sm text-slate-400">{hotel.address || 'Address unavailable'}</p>
                      <div className="mt-2 flex items-center justify-between text-sm">
                        <span>⭐ {hotel.rating ?? 'N/A'}</span>
                        <span className="text-cyan-300">View map</span>
                      </div>
                    </a>
                  ))}
                </div>
              </div>

              <div>
                <p className="font-semibold mb-2">Restaurants</p>
                <div className="grid gap-3 sm:grid-cols-2">
                  {restaurants.slice(0, 4).map((restaurant, idx) => (
                    <a key={`${restaurant.name || idx}`} href={restaurant.maps_url} target="_blank" rel="noreferrer" className="block rounded-xl border border-slate-600 bg-slate-900 p-4 hover:border-cyan-400 transition">
                      <p className="font-semibold">{restaurant.name || 'Restaurant'}</p>
                      <p className="text-sm text-slate-400">{restaurant.address || 'Address unavailable'}</p>
                      <div className="mt-2 flex items-center justify-between text-sm">
                        <span>⭐ {restaurant.rating ?? 'N/A'}</span>
                        <span className="text-cyan-300">View map</span>
                      </div>
                    </a>
                  ))}
                </div>
              </div>

              {safety && (
                <div className="space-y-2">
                  <p className="font-semibold">Safety places</p>
                  <p>Police: {policePlaces.length} locations</p>
                  <p>Hospitals: {hospitalPlaces.length} locations</p>
                  <p className="bg-green-600 inline-block px-2 py-1 rounded-full">Safety Score: 8.8/10</p>
                </div>
              )}

              <div>
                <p className="font-semibold mb-2">Itinerary</p>
                <div className="space-y-3">
                  {itinerary.map((day, idx) => (
                    <div key={`${day.day || idx}`} className="rounded-xl border border-slate-600 bg-slate-900 p-4">
                      <div className="flex items-center justify-between gap-2">
                        <h3 className="font-semibold text-lg">{day.day}</h3>
                        <span className="text-xs text-cyan-300">Est. ₹{day.estimated_cost?.total ?? 'N/A'}</span>
                      </div>
                      <div className="mt-3 grid gap-3 text-sm">
                        <div>
                          <p className="text-slate-400">Hotel</p>
                          <p className="font-medium">{day.hotel?.name || 'N/A'}</p>
                          <p className="text-slate-500">₹{day.estimated_cost?.hotel ?? 'N/A'}</p>
                        </div>
                        <div>
                          <p className="text-slate-400">Restaurant</p>
                          <p className="font-medium">{day.restaurant?.name || 'N/A'}</p>
                          <p className="text-slate-500">₹{day.estimated_cost?.restaurant ?? 'N/A'}</p>
                        </div>
                        <div>
                          <p className="text-slate-400">Visit</p>
                          <p className="font-medium">{day.visit?.name || form.destination}</p>
                          <p className="text-slate-500">₹{day.estimated_cost?.visit ?? 'N/A'}</p>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </div>
        )}

        {panicVisible && (
          <button onClick={() => alert(`Emergency points:\nPolice: ${result.police.length} nearby\nHospitals: ${result.hospitals.length} nearby`)} className="fixed bottom-8 right-8 bg-red-600 hover:bg-red-500 text-white px-4 py-3 rounded-full shadow-xl z-50">
            🚨 Emergency Help
          </button>
        )}
      </section>
    </motion.div>
  );
}
